"""OBSOLETE (the zombie pose search is retired, A5; the pose is unchanged and the camera adapts to it; David 2026-10-22, M153, M162): the eagle camera is fixed to the torso and there is no neck. Kept until the B2.13 cleanup deletes it; it imports code that no longer exists and does not run.

Side-by-side comparison image of home poses (David 2026-10-19): the current pose A and the home pose search's ranks 1 to 3, one column per pose, rows: the robot from the front, from its
left side (both from outside, the same viewpoint relative to the robot for every pose), and the eagle camera's image. Report only: nothing in the config is changed, no pose is applied.

    source .venv/bin/activate
    MUJOCO_GL=egl python experiments/home_pose_compare.py [--out data/home_pose_search/compare_widest_range] [--tag widest_range] [--ranks 1 2 3]

Each pose is drawn at its own stance: pose A at the current staging stance (the finder's output for A); ranks 2 and 3 at the stance the search evaluated them at (the search's offset and
pedestal height, data/home_pose_search/evals.jsonl); rank 1 at the stance the finder rerun under the new checks and ranking chose (data/home_pose_search/search_rank1_widest_range/summary.json), or at its
search stance if that run found none (the label says which). The neck is at its framing pose, the arms at home, the fingers open.

Labels, each in green if the requirement (src/task_config.STANCE_REQUIREMENTS) is met and red if not: occlusion (the robot's hidden share of the beaker's and the hotplate's pixels in the eagle
image: beaker 0 %, hotplate 20 %), framing slack (>= 10 %, grippers in the frame), the smallest distance of the arms to the hotplate with the beaker (>= 40 mm) and the fingers alone to the hotplate
(>= 40 mm), the neck spread (<= 0.06 rad) and the finder's tolerance at the stance (the xy distance to the edge of the reachable region, from the grasp maps; information, no limit).
Writes comparison.png and comparison.json under --out (temporary file, checked, then renamed).
"""

import argparse
import gc
import json
import math
import os
import sys
from pathlib import Path

PROJECT_ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(PROJECT_ROOT))
sys.path.insert(0, str(PROJECT_ROOT / "experiments"))
if not os.environ.get("DISPLAY"):
    os.environ.setdefault("MUJOCO_GL", "egl")

import cv2  # noqa: E402
import mujoco  # noqa: E402
import numpy as np  # noqa: E402

import home_pose_candidates as HPC  # noqa: E402
import home_pose_search as HPS  # noqa: E402
import stance_from_map as SFM  # noqa: E402
from src import robot_specs  # noqa: E402
from src.furniture_map import FurnitureMap  # noqa: E402
from src.neck import set_neck_pose  # noqa: E402
from src.stance_checks import occlusion_ok  # noqa: E402
from src.stance_finder import region_scores  # noqa: E402
from src.task_config import STANCE_CFG, STANCE_REQUIREMENTS as REQ  # noqa: E402

CELL = (480, 360)                      # width, height of one view
HEADER_H = 306
GREEN, RED, GREY, WHITE = (60, 190, 60), (60, 60, 230), (170, 170, 170), (255, 255, 255)      # BGR


def tolerance_fn(ev, heading):
    """The finder's tolerance (metres) at a stance: the left arm's valid-region score of the 24 grasp points at (x, y, pedestal command), from the grasp maps; independent of the home pose."""
    maps = SFM.load_maps(PROJECT_ROOT / "data" / "reach_map")
    m = ev.m
    furniture = FurnitureMap.from_model(m, mujoco.MjData(m), exclude_bodies=("task_beaker",))
    pts = [{"p": p.tolist(), "arm": "left", "bin": None} for p in ev.ctx.P]
    qs = np.round(np.arange(0.0, 0.3001, 0.01), 4)
    X, Y, S = region_scores(pts, maps, furniture, ev.ctx.rg, heading, qs, cfg=STANCE_CFG)
    S = S["left"]
    xs, ys = X[0], Y[:, 0]
    return lambda x, y, q: float(S[int(np.argmin(abs(qs - q))), int(np.argmin(abs(ys - y))), int(np.argmin(abs(xs - x)))])


def views(ev, st, targets):
    """The three images (RGB) of the robot at the stance: front, left side, eagle camera. The outside viewpoints are fixed relative to the robot: the same distance, height and angle."""
    chk, m = ev.chk, ev.m
    chk.place(st)
    d = chk.d
    set_neck_pose(m, d, robot_specs.NECK_SPECS, [targets[n] for n in robot_specs.NECK_SPECS["active_joints"]])
    mujoco.mj_forward(m, d)
    heading = math.degrees(st[2])
    focus = np.mean([d.body("openarm_left_hand_tcp").xpos, d.body("openarm_right_hand_tcp").xpos, d.body("task_beaker").xpos, d.body("task_hotplate").xpos], axis=0)
    focus[2] = float(ev.ctx.top) + 0.40                      # up so that the neck and the eagle camera are in the picture too
    out = {}
    r = mujoco.Renderer(m, CELL[1], CELL[0])
    for name, az, dist in (("front", heading + 180.0, 1.5), ("side", heading - 90.0, 1.9)):
        cam = mujoco.MjvCamera()
        cam.type = mujoco.mjtCamera.mjCAMERA_FREE
        cam.lookat[:] = focus
        cam.distance, cam.azimuth, cam.elevation = dist, az, -15.0
        r.update_scene(d, camera=cam)
        out[name] = r.render().copy()
    r.update_scene(d, camera="eagle_cam")
    out["eagle"] = r.render().copy()
    r.close()
    return out


def measure(ev, st, tol):
    """All the numbers of one pose at its stance."""
    chk = ev.chk
    ns = chk.neck_spread(st)
    oc = chk.occlusion(st, ns["targets"])
    fr = chk.framing_slack(st)
    cl = ev.clearances(st)
    return {"stance": [float(st[0]), float(st[1]), math.degrees(st[2]), float(st[3])], "tolerance_cm": 100 * tol(st[0], st[1], st[3]), "occlusion": oc, "framing_slack": fr["slack"], "framing_limit": fr["limit"],
            "neck_spread": ns["spread"], "arms_to_hotplate_and_beaker_mm": cl["hotplate+beaker"]["mm"], "fingers_to_hotplate_mm": cl["fingers vs hotplate"]["mm"], "fingers_to_bench_mm": cl["fingers vs bench"]["mm"],
            "arms_to_placed_beaker_mm": cl["arms to a beaker standing on the hotplate"]["mm"], "joint_margin_deg": ev.joint_margins()["min_deg"], "targets": ns["targets"]}


def put(img, text, x, y, color=WHITE, scale=0.55):
    cv2.putText(img, text, (x, y), cv2.FONT_HERSHEY_SIMPLEX, scale, color, 1, cv2.LINE_AA)


def tag(img, text, x, y, scale=0.7):
    """A label that reads on any background: white text on a dark box."""
    (w, h), base = cv2.getTextSize(text, cv2.FONT_HERSHEY_SIMPLEX, scale, 2)
    cv2.rectangle(img, (x - 4, y - h - 6), (x + w + 6, y + base + 4), (30, 30, 30), -1)
    cv2.putText(img, text, (x, y), cv2.FONT_HERSHEY_SIMPLEX, scale, WHITE, 2, cv2.LINE_AA)


def header(title, note, r):
    h = np.zeros((HEADER_H, CELL[0], 3), np.uint8)
    h[:] = (38, 38, 38)
    oc, lim = r["occlusion"], REQ["occlusion_max_hidden"]
    ok_b, ok_h = occlusion_ok(oc, {"beaker": lim["beaker"]}), occlusion_ok(oc, {"hotplate": lim["hotplate"]})
    put(h, title, 8, 24, WHITE, 0.8)
    put(h, note, 8, 46, GREY, 0.45)
    st = r["stance"]
    put(h, f"stance x {st[0]:.3f} y {st[1]:.3f}, pedestal {st[3]:.2f} m", 8, 68, GREY, 0.5)
    rows = [
        (f"beaker hidden {100 * oc['beaker_hidden_frac']:.1f} %  (limit {100 * lim['beaker']:.0f} %)", ok_b),
        (f"hotplate hidden {100 * oc['hotplate_hidden_frac']:.1f} %  (limit {100 * lim['hotplate']:.0f} %)", ok_h),
        (f"framing slack {100 * r['framing_slack']:.1f} %  (>= {100 * REQ['framing_min_slack']:.0f} %; {r['framing_limit']})", r["framing_slack"] >= REQ["framing_min_slack"]),
        (f"arms / fingers to hotplate {r['arms_to_hotplate_and_beaker_mm']:.0f} / {r['fingers_to_hotplate_mm']:.0f} mm  (>= 40)", min(r["arms_to_hotplate_and_beaker_mm"], r["fingers_to_hotplate_mm"]) >= 40.0),
        (f"arms to a beaker placed on it {r['arms_to_placed_beaker_mm']:.0f} mm  (>= 40)", r["arms_to_placed_beaker_mm"] is not None and r["arms_to_placed_beaker_mm"] >= 40.0),
        (f"fingers to bench {r['fingers_to_bench_mm']:.0f} mm  (>= 40)", r["fingers_to_bench_mm"] >= 40.0),
        (f"neck spread {r['neck_spread']:.3f} rad  (<= {REQ['neck_max_spread']})", r["neck_spread"] <= REQ["neck_max_spread"]),
        (f"joint margin {r['joint_margin_deg']:.0f} deg  (>= 10)", r["joint_margin_deg"] >= 10.0),
        (f"finder tolerance {r['tolerance_cm']:.1f} cm", None),
    ]
    for i, (text, ok) in enumerate(rows):
        put(h, text, 8, 98 + 22 * i, WHITE if ok is None else (GREEN if ok else RED), 0.5)
    return h


def main():
    ap = argparse.ArgumentParser(description=__doc__.split("\n")[1])
    ap.add_argument("--out", default=str(PROJECT_ROOT / "data" / "home_pose_search" / "compare_widest_range"))
    ap.add_argument("--tag", default="widest_range", help="the finder rerun folder to read: search_rank<N>_<tag> (rank 1's stance)")
    ap.add_argument("--ranks", type=int, nargs="*", default=[1, 2, 3])
    args = ap.parse_args()
    out = Path(args.out)
    out.mkdir(parents=True, exist_ok=True)
    search_dir = PROJECT_ROOT / "data" / "home_pose_search"
    best = HPS.load_best(search_dir, max(args.ranks))
    items = [("A (current)", list(HPC.CANDIDATES["A"]), tuple(HPC.CURRENT_STANCE), "stance: the current one (finder output for A)")]
    for rank in args.ranks:
        r = best[rank - 1]
        dx, dy = r["offset_cm"]
        st, note = (HPC.CURRENT_STANCE[0] + 0.01 * dx, HPC.CURRENT_STANCE[1] + 0.01 * dy, HPC.CURRENT_STANCE[2], r["height"]), "stance: where the search evaluated it"
        fs = search_dir / f"search_rank{rank}_{args.tag}" / "open_b45_selected.json"
        if fs.exists():
            ch = json.loads(fs.read_text())["chosen"]
            if ch:
                st, note = (ch["x"], ch["y"], math.radians(ch["heading_deg"]), ch["q"]), "stance: the finder's, new checks"
            else:
                note = "finder (new checks) found no stance; at the search's"
        items.append((f"rank {rank}", r["q_deg"], st, note))
    columns, rows_json = [], []
    for title, q, st, note in items:
        HPC.set_home(q)
        ev = HPC.Evaluator()
        tol = tolerance_fn(ev, st[2])
        res = measure(ev, st, tol)
        imgs = views(ev, st, res["targets"])
        print(f"{title}: {note}; stance {np.round(st, 3).tolist()}; beaker {100 * res['occlusion']['beaker_hidden_frac']:.1f} % hidden, hotplate {100 * res['occlusion']['hotplate_hidden_frac']:.1f} % hidden, "
              f"framing slack {100 * res['framing_slack']:.1f} %, arms to hotplate+beaker {res['arms_to_hotplate_and_beaker_mm']:.0f} mm, tolerance {res['tolerance_cm']:.1f} cm", flush=True)
        col = np.vstack([header(title, note, res)] + [cv2.cvtColor(imgs[k], cv2.COLOR_RGB2BGR) for k in ("front", "side", "eagle")])
        for k, label in zip(range(3), ("front", "left side", "eagle camera")):
            tag(col, label, 8, HEADER_H + CELL[1] * k + 28)
        columns.append(col)
        rows_json.append({"name": title, "q_deg": list(map(float, q)), "note": note, **{k: v for k, v in res.items() if k != "targets"}})
        del ev
        gc.collect()
    img = np.hstack([np.pad(c, ((0, 0), (0, 4), (0, 0))) for c in columns])
    tmp = out / "comparison.png.tmp.png"
    cv2.imwrite(str(tmp), img)
    assert cv2.imread(str(tmp)) is not None and cv2.imread(str(tmp)).shape == img.shape
    os.replace(tmp, out / "comparison.png")
    SFM.save(out / "comparison.json", rows_json)
    print(f"COMPARE DONE {out / 'comparison.png'}", flush=True)


if __name__ == "__main__":
    main()
